action.code:
if (n == 0ul) {
    return dcomp(1.0, 0.0);
}
if (alpha == dcomp(0.0, 0.0)) {
    return dcomp(0.0, 0.0);
}
const double pi = std::acos(-1.0);
if (n <= 20ul) {
    dcomp num = std::pow(alpha, static_cast<int>(n));
    double denom = std::sqrt(std::tgamma(static_cast<double>(n) + 1.0));
    return num / denom;
}
double a_abs = std::abs(alpha);
double n_d = static_cast<double>(n);
double log_coeff = n_d * std::log(a_abs)
    - 0.5 * (n_d * std::log(n_d) - n_d + 0.5 * std::log(2.0 * pi * n_d));
double magnitude = std::exp(log_coeff);
double phase = n_d * std::arg(alpha);
return std::polar(magnitude, phase);

